@push('scripts')<script>(()=>{const type=document.getElementById('scheduleTargetType');const asset=document.getElementById('scheduleAssetField');const category=document.getElementById('scheduleCategoryField');const assetSelect=asset?.querySelector('select');const categorySelect=category?.querySelector('select');const sync=()=>{const byCategory=type?.value==='category';asset?.classList.toggle('d-none',byCategory);category?.classList.toggle('d-none',!byCategory);if(assetSelect){assetSelect.disabled=byCategory;assetSelect.required=!byCategory;}if(categorySelect){categorySelect.disabled=!byCategory;categorySelect.required=byCategory;}};type?.addEventListener('change',sync);sync();})();</script>@endpush
